/**
 *  The best journey of a leg on the travel days of a pass, for one number of days the journey
 *  uses and one first date. The solve of the whole trip picks among these and the journeys on
 *  single tickets.
 */
export type PassJourneyOption = {
	/**  The journey. */
	journey: Journey,
	/**  The journey's cost in minutes of train travel, without the price. */
	cost_minutes: number,
	/**
	 *  What the pass does not cover, such as reservations and the night accommodation, in
	 *  euro cents. The median of the estimate.
	 */
	price_cents: EuroCents,
	/**  How many travel days the journey uses. */
	days: PassDays,
	/**  The first travel day it uses, the date its first covered train leaves on. */
	first_date: string,
};

/**
 *  What a pass option of a leg costs, as the choice of a pass sees it. It mirrors
 *  `PassJourneyOption` without the journey.
 */
export type PassOptionSummary = {
	/**  The journey's cost in minutes of train travel, without the price. */
	cost_minutes: number,
	/**  What the pass does not cover, in euro cents. */
	price_cents: EuroCents,
	/**  How many travel days the journey uses. */
	days: PassDays,
	/**  The first travel day it uses. */
	first_date: string,
};

/**
 *  One way of covering the whole trip: single tickets everywhere, or a pass with the legs that
 *  ride on its travel days.
 */
export type PassScenario = {
	/**  The pass, or `None` when every leg takes single tickets. */
	pass: ScenarioPass | null,
	/**
	 *  For each leg in the order the request gave them, the pass option it takes as an index
	 *  into its pass options, or `None` when it takes single tickets.
	 */
	pass_option_of_leg: (number | null)[],
	/**  The total cost of the journeys in minutes of train travel. */
	minutes: number,
	/**  The total price of the tickets, the pass included. The median of the estimates. */
	price: EuroCents,
};

/**
 *  One leg of a trip as the choice of a pass sees it: the journey it takes on single tickets
 *  and its best journeys on the travel days of a pass.
 */
export type PassScenarioLeg = {
	/**  The leg's departure date. */
	date: string,
	/**
	 *  The cost of the journey the leg takes on single tickets, in minutes of train travel,
	 *  without the price.
	 */
	single_cost_minutes: number,
	/**
	 *  The median price of that journey's tickets. `None` when no price is known, which the
	 *  choice counts as nothing.
	 */
	single_price: EuroCents | null,
	/**  The leg's pass options, in the order of `LegPlan::pass_options`. */
	pass_options: PassOptionSummary[],
};

/**  Where a new place goes in the itinerary. */
export type PlaceInsertionPoint = 
/**  Before the place at this index, or at the end when the index equals the place count. */
{ AtIndex: number } | 
/**
 *  The position that adds the least straight-line distance to the itinerary, including a new
 *  origin before the first place or a new destination after the last.
 */
"LeastAddedDistance";

/**  A place found by a geocoding search. */
export type PlaceSearchResult = {
	/**  Name of the place, such as "Vienna" or "Wien Hauptbahnhof". */
	name: string,
	/**  Context that tells places with the same name apart, such as "Lower Austria, Austria". */
	context: string,
	/**  Location of the place. */
	coordinates: GeoCoordinates,
};

/**  How long the traveller stays at a via place. */
export type PlaceStay = 
/**  The traveller sleeps here this many nights. */
({ Nights: number }) & { SameDay?: never } | 
/**  The traveller leaves on the day of arrival. */
({ SameDay: {
	/**  Replaces the trip's default same-day stay range for this place. */
	stay_range_override: SameDayStayRange | null,
	/**  Turns extra stay time into a small bonus in scoring. */
	prefers_longer_stay: boolean,
} }) & { Nights?: never };

/**
 *  Time windows of a place that replace the trip's defaults. The arrival window applies to the
 *  leg that reaches the place, and the departure window to the leg that leaves it.
 */
export type PlaceWindowOverride = 
/**  Only the arrival window differs from the default. */
({ Arrival: DailyTimeWindow }) & { Both?: never; Departure?: never } | 
/**  Only the departure window differs from the default. */
({ Departure: DailyTimeWindow }) & { Arrival?: never; Both?: never } | 
/**  Both windows differ from the defaults. */
({ Both: TravelDayWindows }) & { Arrival?: never; Departure?: never };

/**  Counts planning runs within one session. A newer run replaces the results of older ones. */
export type PlanningRunId = number;

/**  Messages from a planning session to the frontend. */
export type PlanningSessionEvent = 
/**  The trip changed outside the frontend, for example when reverse geocoding named a place. */
({ TripChanged: Trip }) & { LegExtrasPlanned?: never; LegPlanned?: never; NearbyDaySuggested?: never; PlanningFinished?: never; PlanningStarted?: never } | 
/**  A run started. Legs it replans are pending until their `LegPlanned` event. */
({ PlanningStarted: {
	/**  Identifies the run. */
	run_id: PlanningRunId,
	/**  Places whose arriving legs this run replans. */
	replanned_arrival_place_ids: TripPlaceId[],
} }) & { LegExtrasPlanned?: never; LegPlanned?: never; NearbyDaySuggested?: never; PlanningFinished?: never; TripChanged?: never } | 
/**  One leg of a run finished its main plan. */
({ LegPlanned: {
	/**  Identifies the run. */
	run_id: PlanningRunId,
	/**  Place at which the planned leg arrives. */
	arrival_place_id: TripPlaceId,
	/**  The planned journeys, or why there are none. */
	result: LegPlanningResult,
	/**
	 *  Whether a `LegExtrasPlanned` event for the leg is still to come, so the plan has no
	 *  cheaper or faster journey and no pass options yet.
	 */
	extras_pending?: boolean,
} }) & { LegExtrasPlanned?: never; NearbyDaySuggested?: never; PlanningFinished?: never; PlanningStarted?: never; TripChanged?: never } | 
/**
 *  Every leg of a run finished its main plan. The searches for the extras of the legs
 *  follow.
 */
({ PlanningFinished: {
	/**  Identifies the run. */
	run_id: PlanningRunId,
} }) & { LegExtrasPlanned?: never; LegPlanned?: never; NearbyDaySuggested?: never; PlanningStarted?: never; TripChanged?: never } | 
/**
 *  The searches after the main plan of a leg finished. Sent for a leg whose `LegPlanned`
 *  event said they were pending, or whose plan from an earlier run still waited for them.
 */
({ LegExtrasPlanned: {
	/**  Identifies the run. */
	run_id: PlanningRunId,
	/**  Place at which the leg arrives. */
	arrival_place_id: TripPlaceId,
	/**  What the searches found. */
	extras: LegExtras,
} }) & { LegPlanned?: never; NearbyDaySuggested?: never; PlanningFinished?: never; PlanningStarted?: never; TripChanged?: never } | 
/**
 *  A day before or after a leg's date is much better for the leg. Sent after the extras
 *  of the legs, and a leg that is planned again loses its suggestion.
 */
({ NearbyDaySuggested: {
	/**  Identifies the run. */
	run_id: PlanningRunId,
	/**  Place at which the leg arrives. */
	arrival_place_id: TripPlaceId,
	/**  The better day. */
	suggestion: NearbyDaySuggestion,
} }) & { LegExtrasPlanned?: never; LegPlanned?: never; PlanningFinished?: never; PlanningStarted?: never; TripChanged?: never };

/**  A price with the confidence in it and its source. */
export type Price = {
	/**  The lowest price the source allows. Equal to `high` for a formula. */
	low: EuroCents,
	/**  The highest price the source allows. */
	high: EuroCents,
	/**  How sure the price is. */
	kind: PriceKind,
	/**  Where the price comes from. */
	source: PriceSource,
	/**  The price in the currency the source gave it in, when that is not the euro. */
	original?: ForeignAmount | null,
};

/**
 *  How sure a price is, from the most to the least. The order is the order of confidence, so the
 *  lowest confidence of several prices is their maximum.
 */
export type PriceKind = 
/**  A published price list or a function of the distance. It is exact for the fare it names. */
"Formula" | 
/**  A quote from an operator's interface for a train and a date. */
"Live" | 
/**  A rough estimate with a lowest and a highest price. */
"Range";

/**  Where a price comes from. */
export type PriceSource = {
	/**  Name of the source, such as "Interrail price list". */
	name: string,
	/**  What the source says about how the price was found, for the tooltip. */
	note: string,
	/**  The day the source was valid or fetched. */
	as_of: string | null,
	/**  A page where the traveller can check the price. */
	page: string | null,
};

/**  A sum of prices with the lowest confidence among its parts. */
export type PriceTotal = {
	/**  The sum of the lowest prices. */
	low: EuroCents,
	/**  The sum of the highest prices. */
	high: EuroCents,
	/**  The lowest confidence of any part. */
	kind: PriceKind,
};

/**  How many minutes of travel time one euro is worth in scoring, in hundredths of a minute. */
export type PriceWeight = number;

/**  What the map showed when the traveller made the report. */
export type ProblemReportView = {
	/**  The place selected in the list or on the map, if any. */
	selected_place_id: TripPlaceId | null,
	/**  Centre of the map. */
	map_center: GeoCoordinates,
	/**  Zoom level of the map. */
	map_zoom: number | null,
};

/**  One train of a run, as the price model reads it. */
export type RideDescription = {
	/**  The operator as the app names it, such as `db-fernverkehr`. Empty when not known. */
	operator: string,
	/**  Category of the train, such as "ICE". */
	category: string,
	/**  Country of the boarding station as a two-letter code, if known. */
	from_country: string | null,
	/**  Country of the alighting station, if known. */
	to_country: string | null,
	/**  Length of the ride along its line, in metres. */
	distance_metres: number,
	/**  Whether the train has couchettes or sleepers. */
	offers_berths: boolean,
};

/**  The run of trains that one ticket covers, as the price model reads it. */
export type RunDescription = {
	/**  Name of the station where the run starts. */
	from_station: string,
	/**  Name of the station where the run ends. */
	to_station: string,
	/**  Departure of the first train on the local clock of its station. */
	local_departure: string,
	/**  The trains of the run in order. */
	rides: RideDescription[],
};

/**
 *  Time spent at a same-day stop, measured from train arrival to train departure.
 * 
 *  The maximum is stored as a length beyond the minimum, so a maximum below the minimum cannot
 *  be represented.
 */
export type SameDayStayRange = {
	/**  Shortest acceptable stay. */
	minimum: DurationMinutes,
	/**  How much longer than `minimum` the stay may be. `None` means no upper bound. */
	maximum_beyond_minimum: DurationMinutes | null,
};

/**  The pass of a scenario and its window of validity. */
export type ScenarioPass = {
	/**  The pass's name, such as "Interrail Global Pass, 4 days in 1 month". */
	name: string,
	/**  The first day of validity. */
	first_valid_date: string,
	/**  The last day of validity. */
	last_valid_date: string,
	/**  The price of the pass for the traveller. */
	price: EuroCents,
};

/**  A span of time the planner searched in, such as a departure window. */
export type SearchedWindow = {
	/**  First moment of the span. */
	start: UnixTimeMinutes,
	/**  Moment the span ends. */
	end: UnixTimeMinutes,
};

/**  A search on a booking site whose booking link opens its start page. */
export type SiteSearch = {
	/**  Code of the first station on the site. */
	origin_code: string,
	/**  Code of the last station on the site. */
	destination_code: string,
	/**  Departure of the first train on the local clock of its station, as `YYYY-MM-DDTHH:MM`. */
	local_departure: string,
};

/**  Largest distance from a place to a station the planner may use, from 100 m to 50 km. */
export type StationSearchRadius = number;

/**
 *  A way off the train, between a place and a station or between two stations. Its duration
 *  is an estimate from the straight-line distance, not a planned connection.
 */
export type StationWay = {
	/**  Estimated time the way takes. */
	duration: DurationMinutes,
	/**  Straight-line distance of the way. */
	distance_meters: number,
	/**  How the estimate assumes the traveller goes. */
	mode: WayToStationMode,
};

/**  What a strategy is. */
export type StrategyKind = 
/**  Single tickets for every ride. */
"SingleTickets" | 
/**  An Interrail pass for the days where it pays, with single tickets for the other rides. */
"Pass";

/**  One ticket to buy. */
export type TicketItem = {
	/**  Identifies the ticket within its strategy, and is what a ride's cover refers to. */
	id: number,
	/**  What the ticket is. */
	product: TicketProduct,
	/**  Short name, such as "Interrail Global Pass, 7 days in 1 month, 2nd class, adult". */
	title: string,
	/**  What the ticket covers, in words. */
	detail: string,
	/**  Indices into `TicketPlan::rides` of the rides the ticket covers. */
	ride_indices: number[],
	/**  What the ticket costs. */
	price: Price,
	/**  Where to buy it. */
	booking_link: BookingLink | null,
	/**  What to ask a booking site for the price of this ticket, if a site can tell it. */
	live_quote_request: LiveQuoteRequest | null,
};

/**  The chosen journey of one leg, as the frontend hands it over to price the trip. */
export type TicketLeg = {
	/**  The place the leg arrives at. */
	arrival_place_id: TripPlaceId,
	/**  The journey the traveller rides. */
	journey: Journey,
	/**  The stations the journey's rides refer to. */
	stations: LegPlanStation[],
};

/**  The tickets a trip needs for one traveller. */
export type TicketPlan = {
	/**  The trains of the trip in travel order. */
	rides: TicketRide[],
	/**  The ways to cover them, the cheapest at the middle of the ranges first. */
	strategies: TicketStrategy[],
	/**  Name of the traveller the plan is for, or `None` when the plan assumes an adult. */
	traveller_name: string | null,
	/**  Remarks about the plan as a whole, such as an assumed traveller. */
	notes: string[],
};

/**  How tickets for the trip are chosen. The options are independent switches. */
export type TicketPreferences = {
	/**  Whether the optimizer compares an Interrail pass with single tickets. */
	consider_passes: boolean,
	/**  Whether children travelling with an adult on a pass are priced as free. */
	consider_families: boolean,
	/**  The kind of single ticket to price. */
	fare_type: FareType,
	/**  Whether optional seat reservations are bought, so they count in the price. */
	reserve_optional_seats: boolean,
	/**
	 *  Whether prices are looked up on the booking sites of operators. These sites are not
	 *  meant to be read by programs, so the lookup is a choice.
	 */
	live_prices: boolean,
	/**
	 *  The day tickets are assumed to be bought, which decides the booking window. `None` means
	 *  today.
	 */
	assumed_purchase_date: string | null,
};

/**  What a ticket is. */
export type TicketProduct = 
/**  A ticket for one train or a run of trains on one day. */
"SingleTicket" | 
/**  An Interrail pass. */
{ InterrailPass: {
	/**  The `id` of the pass in the price list. */
	pass_id: string,
	/**  The first day of validity. */
	first_valid_date: string,
	/**  The days the pass is used on. For a continuous pass, every day of validity. */
	travel_days: string[],
} } | 
/**  A seat reservation for a train that a pass covers. */
"Reservation" | 
/**  Berth or sleeper accommodation on a night train. */
"NightAccommodation";

/**  A train of the trip as the tickets screen shows it. */
export type TicketRide = {
	/**  The place the leg of the ride arrives at. */
	leg_arrival_place_id: TripPlaceId,
	/**  How the train is shown. */
	train_label: TrainLabel,
	/**  Name of the station where the traveller boards. */
	from_name: string,
	/**  Name of the station where the traveller leaves the train. */
	to_name: string,
	/**  Departure. */
	departure_time: UnixTimeMinutes,
	/**  Arrival. */
	arrival_time: UnixTimeMinutes,
	/**  IANA time zone of the boarding station. */
	time_zone: string,
	/**  Whether the train has berths. */
	offers_berths: boolean,
};

/**  A way to cover every ride of the trip. */
export type TicketStrategy = {
	/**  What the strategy is. */
	kind: StrategyKind,
	/**  Short name for the comparison. */
	title: string,
	/**  The tickets to buy. */
	items: TicketItem[],
	/**  What the strategy costs in all. */
	total: PriceTotal,
	/**  For each ride of `TicketPlan::rides`, the ids of the tickets that cover it. */
	covers: number[][],
	/**  Things the traveller should know, such as rides that no ticket was priced for. */
	notes: string[],
};

/**  How a train is shown to the traveller, such as "ICE 27". */
export type TrainLabel = {
	/**  Product or category, such as "ICE", "RJX" or "NJ". */
	category: string,
	/**  Train number within the category. */
	number: string,
	/**
	 *  The operator as the app names it, such as `db-fernverkehr` or `regiojet`. Empty in plans
	 *  stored without it.
	 */
	operator?: string,
	/**
	 *  The operating agency as the timetable names it, such as "DB Fernverkehr AG". Empty in
	 *  plans stored without it.
	 */
	agency?: string,
};

/**  One train ridden from boarding to alighting. */
export type TrainRide = {
	/**  Station where the traveller boards. */
	boarding_station: LegPlanStationIndex,
	/**  Departure from the boarding station. */
	departure_time: UnixTimeMinutes,
	/**  Station where the traveller leaves the train. */
	alighting_station: LegPlanStationIndex,
	/**  Arrival at the alighting station. */
	arrival_time: UnixTimeMinutes,
	/**  How the train is shown to the traveller. */
	train_label: TrainLabel,
	/**  Whether the train has couchettes or sleepers, whatever the leg's travel mode. */
	offers_berths: boolean,
	/**  Stations the train stops at between boarding and alighting, in order. */
	intermediate_station_coordinates: GeoCoordinates[],
	/**
	 *  Every point of the line between boarding and alighting, in order: the stops and the
	 *  stations the train most likely passes without stopping. Empty in plans stored
	 *  without it, in which case the stops describe the line.
	 */
	path_coordinates?: GeoCoordinates[],
};

/**  A transfer from the previous ride, followed by the next ride. */
export type TransferAndRide = {
	/**  Time from arriving on the previous ride to departing on this one. */
	transfer_duration: DurationMinutes,
	/**  The next ride. */
	ride: TrainRide,
};

/**
 *  Trade-off between travel time and transfers. 0 favors the shortest travel time, 100 the
 *  fewest transfers.
 */
export type TransferAversion = number;

/**  Travel class for passes and fares. */
export type TravelClass = 
/**  First class. */
"First" | 
/**  Second class. */
"Second";

/**  Local time windows for departing and arriving on travel days. */
export type TravelDayWindows = {
	/**  Window in which the first train of a leg departs. */
	departure: DailyTimeWindow,
	/**  Window in which the last train of a leg arrives. */
	arrival: DailyTimeWindow,
};

/**  A person who travels on a trip. */
export type Traveller = {
	/**  Identifies the traveller across trips. */
	id: TravellerId,
	/**  Name shown in lists. */
	name: string,
	/**  Date of birth, from which the age group on a day follows. */
	birth_date: string,
	/**  Country of residence as a two-letter code, which decides the Interrail residence rule. */
	residence_country: string,
	/**  Class the traveller books. */
	travel_class: TravelClass,
	/**  Discount cards the traveller owns. */
	discount_cards: DiscountCard[],
	/**  An Interrail pass the traveller already owns, if any. */
	owned_pass: OwnedInterrailPass | null,
	/**  The traveller whose pass a child travels with, if any. */
	accompanying_traveller: TravellerId | null,
};

/**  Identifies a traveller profile, which lives outside any single trip. */
export type TravellerId = string;

/**  A planned multi-stop train trip. */
export type Trip = {
	/**  Identifies the trip across machines. */
	id: TripId,
	/**  Name shown in the trip list. */
	name: string,
	/**  Date of the first leg's departure, before any nights at via places. */
	start_date: string,
	/**  The ordered places of the trip. */
	itinerary: Itinerary,
	/**  Trip-wide planning preferences. */
	preferences: TripPreferences,
	/**  Next free `TripPlaceId` in this trip. IDs of removed places are never reused. */
	next_place_id: number,
	/**  Journeys the traveller picked instead of the planner's pick, at most one per leg. */
	chosen_journeys?: ChosenJourney[],
};

/**  One change to a trip. */
export type TripEdit = 
/**  Changes the trip's name. */
({ RenameTrip: string }) & { AddPlace?: never; ChooseJourney?: never; MovePlace?: never; RemovePlace?: never; RenamePlace?: never; ReorderPlace?: never; SetLegTravelMode?: never; SetPlaceStay?: never; SetPlaceWindowOverride?: never; SetStartDate?: never; SetStationSearchRadius?: never; SetTripPreferences?: never } | 
/**  Changes the date of the first departure. */
({ SetStartDate: string }) & { AddPlace?: never; ChooseJourney?: never; MovePlace?: never; RemovePlace?: never; RenamePlace?: never; RenameTrip?: never; ReorderPlace?: never; SetLegTravelMode?: never; SetPlaceStay?: never; SetPlaceWindowOverride?: never; SetStationSearchRadius?: never; SetTripPreferences?: never } | 
/**  Adds a place. */
({ AddPlace: {
	/**  The place to add. */
	place: NewTripPlace,
	/**  Where the place goes. */
	insert_at: PlaceInsertionPoint,
} }) & { ChooseJourney?: never; MovePlace?: never; RemovePlace?: never; RenamePlace?: never; RenameTrip?: never; ReorderPlace?: never; SetLegTravelMode?: never; SetPlaceStay?: never; SetPlaceWindowOverride?: never; SetStartDate?: never; SetStationSearchRadius?: never; SetTripPreferences?: never } | 
/**  Moves a place to new coordinates. */
({ MovePlace: {
	/**  The place to move. */
	place_id: TripPlaceId,
	/**  The new coordinates. */
	coordinates: GeoCoordinates,
} }) & { AddPlace?: never; ChooseJourney?: never; RemovePlace?: never; RenamePlace?: never; RenameTrip?: never; ReorderPlace?: never; SetLegTravelMode?: never; SetPlaceStay?: never; SetPlaceWindowOverride?: never; SetStartDate?: never; SetStationSearchRadius?: never; SetTripPreferences?: never } | 
/**  Changes the name of a place. */
({ RenamePlace: {
	/**  The place to rename. */
	place_id: TripPlaceId,
	/**  The new name. */
	name: string,
} }) & { AddPlace?: never; ChooseJourney?: never; MovePlace?: never; RemovePlace?: never; RenameTrip?: never; ReorderPlace?: never; SetLegTravelMode?: never; SetPlaceStay?: never; SetPlaceWindowOverride?: never; SetStartDate?: never; SetStationSearchRadius?: never; SetTripPreferences?: never } | 
/**  Changes how far from a place the planner may look for stations. */
({ SetStationSearchRadius: {
	/**  The place to change. */
	place_id: TripPlaceId,
	/**  The new radius. */
	radius: StationSearchRadius,
} }) & { AddPlace?: never; ChooseJourney?: never; MovePlace?: never; RemovePlace?: never; RenamePlace?: never; RenameTrip?: never; ReorderPlace?: never; SetLegTravelMode?: never; SetPlaceStay?: never; SetPlaceWindowOverride?: never; SetStartDate?: never; SetTripPreferences?: never } | 
/**  Sets or clears the time windows that replace the trip's defaults at a place. */
({ SetPlaceWindowOverride: {
	/**  The place to change. */
	place_id: TripPlaceId,
	/**  The new override, or `None` to use the trip's defaults. */
	window_override: PlaceWindowOverride | null,
} }) & { AddPlace?: never; ChooseJourney?: never; MovePlace?: never; RemovePlace?: never; RenamePlace?: never; RenameTrip?: never; ReorderPlace?: never; SetLegTravelMode?: never; SetPlaceStay?: never; SetStartDate?: never; SetStationSearchRadius?: never; SetTripPreferences?: never } | 
/**  Removes a place. */
({ RemovePlace: TripPlaceId }) & { AddPlace?: never; ChooseJourney?: never; MovePlace?: never; RenamePlace?: never; RenameTrip?: never; ReorderPlace?: never; SetLegTravelMode?: never; SetPlaceStay?: never; SetPlaceWindowOverride?: never; SetStartDate?: never; SetStationSearchRadius?: never; SetTripPreferences?: never } | 
/**  Moves a place to another position in the itinerary. */
({ ReorderPlace: {
	/**  The place to move. */
	place_id: TripPlaceId,
	/**  Index of the place after the move. */
	new_index: number,
} }) & { AddPlace?: never; ChooseJourney?: never; MovePlace?: never; RemovePlace?: never; RenamePlace?: never; RenameTrip?: never; SetLegTravelMode?: never; SetPlaceStay?: never; SetPlaceWindowOverride?: never; SetStartDate?: never; SetStationSearchRadius?: never; SetTripPreferences?: never } | 
/**  Changes how long the traveller stays at a via place. */
({ SetPlaceStay: {
	/**  The via place to change. */
	place_id: TripPlaceId,
	/**  The new stay. */
	stay: PlaceStay,
} }) & { AddPlace?: never; ChooseJourney?: never; MovePlace?: never; RemovePlace?: never; RenamePlace?: never; RenameTrip?: never; ReorderPlace?: never; SetLegTravelMode?: never; SetPlaceWindowOverride?: never; SetStartDate?: never; SetStationSearchRadius?: never; SetTripPreferences?: never } | 
/**  Changes whether the leg that arrives at a place includes a night train. */
({ SetLegTravelMode: {
	/**  Place at which the leg arrives. Every place except the origin has one arriving leg. */
	arrival_place_id: TripPlaceId,
	/**  The new travel mode. */
	travel_mode: LegTravelMode,
} }) & { AddPlace?: never; ChooseJourney?: never; MovePlace?: never; RemovePlace?: never; RenamePlace?: never; RenameTrip?: never; ReorderPlace?: never; SetPlaceStay?: never; SetPlaceWindowOverride?: never; SetStartDate?: never; SetStationSearchRadius?: never; SetTripPreferences?: never } | 
/**  Replaces the trip-wide preferences. */
({ SetTripPreferences: TripPreferences }) & { AddPlace?: never; ChooseJourney?: never; MovePlace?: never; RemovePlace?: never; RenamePlace?: never; RenameTrip?: never; ReorderPlace?: never; SetLegTravelMode?: never; SetPlaceStay?: never; SetPlaceWindowOverride?: never; SetStartDate?: never; SetStationSearchRadius?: never } | 
/**  Picks a journey for the leg that arrives at a place, or goes back to the planner's pick. */
({ ChooseJourney: {
	/**  Place at which the leg arrives. */
	arrival_place_id: TripPlaceId,
	/**
	 *  The picked journey, or `None` for the planner's pick. Boxed, because a choice holds
	 *  several train labels and would make every edit as large.
	 */
	choice: JourneyChoice | null,
} }) & { AddPlace?: never; MovePlace?: never; RemovePlace?: never; RenamePlace?: never; RenameTrip?: never; ReorderPlace?: never; SetLegTravelMode?: never; SetPlaceStay?: never; SetPlaceWindowOverride?: never; SetStartDate?: never; SetStationSearchRadius?: never; SetTripPreferences?: never };

/**  Reasons an edit can be rejected. A rejected edit leaves the trip unchanged. */
export type TripEditError = 
/**  The trip has no place with this ID. */
({ UnknownPlace: TripPlaceId }) & { IndexOutOfRange?: never; PlaceHasNoArrivingLeg?: never; PlaceHasNoStay?: never } | 
/**  Only via places have a stay. The origin and the destination do not. */
({ PlaceHasNoStay: TripPlaceId }) & { IndexOutOfRange?: never; PlaceHasNoArrivingLeg?: never; UnknownPlace?: never } | 
/**  The origin has no leg that arrives at it. */
({ PlaceHasNoArrivingLeg: TripPlaceId }) & { IndexOutOfRange?: never; PlaceHasNoStay?: never; UnknownPlace?: never } | 
/**  The index is past the end of the itinerary. */
({ IndexOutOfRange: {
	/**  The rejected index. */
	index: number,
	/**  Number of places in the itinerary. */
	place_count: number,
} }) & { PlaceHasNoArrivingLeg?: never; PlaceHasNoStay?: never; UnknownPlace?: never } | 
/**  The itinerary already has the largest number of places allowed. */
"TooManyPlaces";

/**  Something an edit changed besides what it asked for, shown to the user. */
export type TripEditNotice = 
/**
 *  Two places with an overnight leg between them are no longer adjacent, so the overnight
 *  options of that leg were dropped.
 */
{ OvernightOptionDropped: {
	/**  Place the dropped leg left from. */
	departure_place_id: TripPlaceId,
	/**  Place the dropped leg arrived at. */
	arrival_place_id: TripPlaceId,
} };

/**
 *  The trip after an edit, with the notices the edit produced and the state of the undo
 *  history. Undo and redo return it too, with no notices.
 */
export type TripEditOutcome = {
	/**  The trip after the edit. */
	trip: Trip,
	/**  Side effects of the edit, shown to the user. */
	notices: TripEditNotice[],
	/**  What undo and redo would do after the edit. */
	history: TripHistoryState,
};

/**  What the frontend shows about the history of an open trip. */
export type TripHistoryState = {
	/**  What undo would take back, or `None` when there is nothing to undo. */
	undo_description: string | null,
	/**  What redo would apply again, or `None` when there is nothing to redo. */
	redo_description: string | null,
};

/**  Identifies a trip. A UUID v7, so trips imported from another machine never collide. */
export type TripId = string;

/**  A place the traveller visits, as chosen on the map or through search. */
export type TripPlace = {
	/**  Identifies the place within its trip. */
	id: TripPlaceId,
	/**  Name shown in the itinerary. */
	name: string,
	/**  Point the traveller travels to or from. */
	coordinates: GeoCoordinates,
	/**  Largest distance to a station the planner may use for this place. */
	station_search_radius: StationSearchRadius,
	/**  Replaces the trip's default windows for legs that leave or reach this place. */
	window_override: PlaceWindowOverride | null,
};

/**  Identifies a place within one trip. Unique within that trip only. */
export type TripPlaceId = number;

/**  Trip-wide planning preferences. Places and legs can override some of them. */
export type TripPreferences = {
	/**  Windows for places without their own override. */
	default_windows: TravelDayWindows,
	/**  Trade-off between travel time and transfers. */
	transfer_aversion: TransferAversion,
	/**  Stay range for same-day places without their own override. */
	default_same_day_stay: SameDayStayRange,
	/**  How the planner treats trains the pass does not cover. */
	pass_policy: InterrailPassPolicy,
	/**  Shortest time allowed between arriving on one train and departing on the next. */
	minimum_transfer_time: DurationMinutes,
	/**  Travellers on this trip, referring to profiles from the traveller screen. */
	traveller_ids: TravellerId[],
	/**  Class for passes and fares. */
	travel_class: TravelClass,
	/**  Weight of price against travel time in scoring. */
	price_weight: PriceWeight,
	/**  How tickets are chosen. */
	ticket_preferences: TicketPreferences,
};

/**  Short description of a trip for the trip list. */
export type TripSummary = {
	/**  Identifies the trip. */
	trip_id: TripId,
	/**  Name of the trip. */
	name: string,
	/**  Date of the first departure. */
	start_date: string,
	/**  Number of places in the itinerary. */
	place_count: number,
};

/**  Minutes since the Unix epoch, 1970-01-01 00:00 UTC. */
export type UnixTimeMinutes = number;

/**  A place between the origin and the destination, with the leg that arrives there. */
export type ViaPlace = {
	/**  Travel mode of the leg that ends at this place. */
	arriving_leg_travel_mode: LegTravelMode,
	/**  The place itself. */
	place: TripPlace,
	/**  How long the traveller stays here. */
	stay: PlaceStay,
};

/**  How the planner assumes a traveller covers a way off the train. */
export type WayToStationMode = 
/**  On foot, for ways shorter than a kilometer. */
"Walk" | 
/**  By bus, tram or metro, for longer ways. */
"LocalTransport";

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

